/**
 * Single source of truth for the backend API location on the frontend.
 *
 * The base URL comes from the project .env file via JS/env.js, which is
 * generated by scripts/generate-frontend-env.mjs. Changing API_BASE_URL in the
 * root .env (and running `npm run env:frontend` inside Backend) updates the
 * frontend, so the URL never has to be edited in page code.
 *
 * The fallbacks below keep pages working when env.js is missing:
 * - Local development (including file://) uses the local Express server.
 * - Production assumes the API is served from "<origin>/api".
 */
(function () {
  var LOCAL_HOSTS = ["localhost", "127.0.0.1", "::1"];

  function trimmed(value) {
    return String(value || "").trim().replace(/\/+$/, "");
  }

  var isLocalDev =
    window.location.protocol === "file:" ||
    LOCAL_HOSTS.indexOf(window.location.hostname) !== -1;

  var base = trimmed(window.SASTA_API_BASE);

  if (!base) {
    base = isLocalDev
      ? "http://localhost:4000/api"
      : window.location.origin + "/api";
  }

  window.SASTA_API_BASE = base;
})();
